#[test] fn xml_toolbar_draws_titles_and_handles_navigation(){let mut ui=Ui::default();let mut state=android_xml::LayoutState::default();fixture::install_drawables(&mut state);let bounds=Rect{x:0.,y:0.,width:320.,height:56.};let commands=ui.frame(Input::default(),bounds,0.,|f|{fixture::LAYOUT.render(f,bounds,&mut state);});assert!(commands.iter().any(|c|matches!(c,DrawCommand::Text{text,..} if text.as_ref()=="Inbox")));assert!(commands.iter().any(|c|matches!(c,DrawCommand::Text{text,..} if text.as_ref()=="Personal account")));assert!(commands.iter().any(|c|matches!(c,DrawCommand::Image{..})));let p=Some([24.,28.]);ui.frame(Input{pointer:p,pressed:true,time:1.,..Input::default()},bounds,0.,|f|{fixture::LAYOUT.render(f,bounds,&mut state);});let mut action=None;ui.frame(Input{pointer:p,released:true,time:1.01,..Input::default()},bounds,0.,|f|action=fixture::LAYOUT.render(f,bounds,&mut state));assert_eq!(action,Some("toolbar"));assert!(state.toolbar_navigation_clicked.contains("toolbar"));}
