#[test] fn action_and_overflow_items_report_selected_id(){use bhoo::android_xml::AndroidToolbarMenuItem as Item;let mut ui=Ui::default();let mut state=android_xml::LayoutState::default();fixture::install_drawables(&mut state);state.toolbar_menu_items.insert("toolbar".into(),vec![Item{checkable:false,checked:false,exclusive:false,group_id:0,id:1,label:"Search".into(),icon:Some(MaterialIcon::Search),show_text_with_icon:false,icon_drawable:None,show_as_action:bhoo::android_xml::AndroidShowAsAction::IfRoom,enabled:true,visible:true},Item{checkable:false,checked:false,exclusive:false,group_id:0,id:2,label:"Settings".into(),icon:None,show_text_with_icon:false,icon_drawable:None,show_as_action:bhoo::android_xml::AndroidShowAsAction::Never,enabled:true,visible:true},Item{checkable:false,checked:false,exclusive:false,group_id:0,id:3,label:"Disabled".into(),icon:None,show_text_with_icon:false,icon_drawable:None,show_as_action:bhoo::android_xml::AndroidShowAsAction::Never,enabled:false,visible:true}]);let viewport=Rect{x:0.,y:0.,width:320.,height:400.};let toolbar=Rect{x:0.,y:0.,width:320.,height:56.};let draw=|ui:&mut Ui,state:&mut android_xml::LayoutState,input|{let mut action=None;ui.frame(input,viewport,0.,|f|action=fixture::LAYOUT.render(f,toolbar,state));action};let click=|ui:&mut Ui,state:&mut android_xml::LayoutState,label:&str,time:f64|{let r=ui.semantics().iter().find(|n|n.label.as_ref()==label).unwrap().bounds;let p=Some([r.x+r.width/2.,r.y+r.height/2.]);draw(ui,state,Input{pointer:p,pressed:true,time,..Input::default()});draw(ui,state,Input{pointer:p,released:true,time:time+0.01,..Input::default()})};draw(&mut ui,&mut state,Input::default());assert_eq!(click(&mut ui,&mut state,"Search",1.),Some("toolbar"));assert_eq!(state.toolbar_menu_clicked["toolbar"],1);click(&mut ui,&mut state,"More options",2.);draw(&mut ui,&mut state,Input{time:2.2,..Input::default()});assert_eq!(click(&mut ui,&mut state,"Settings",2.3),Some("toolbar"));assert_eq!(state.toolbar_menu_clicked["toolbar"],2);}
#[test] fn menu_allocation_keeps_required_actions_before_requested_actions(){use bhoo::android_xml::{AndroidToolbarMenuItem as Item,AndroidShowAsAction as Policy,allocate_android_toolbar_actions as allocate};let item=|id,policy,visible|Item{checkable:false,checked:false,exclusive:false,group_id:0,id,label:id.to_string(),icon:None,show_text_with_icon:false,icon_drawable:None,show_as_action:policy,enabled:true,visible};let items=vec![item(1,Policy::IfRoom,true),item(2,Policy::Always,true),item(3,Policy::Never,true),item(4,Policy::Always,false)];assert_eq!(allocate(&items,3),(vec![0,1],vec![2]));assert_eq!(allocate(&items,2),(vec![1],vec![0,2]));assert_eq!(allocate(&items,1),(vec![1],vec![0,2]));}
