#[test] fn xml_menu_vector_drawable_is_painted_for_action(){let mut ui=Ui::default();let mut state=android_xml::LayoutState::default();fixture::install_drawables(&mut state);xml_menu::install_drawables(&mut state);let items=xml_menu::items();let name=items[0].icon_drawable.as_deref().unwrap();assert_eq!(name,"toolbar_vector_search");assert_eq!(state.drawable_tints[name],android_xml::AndroidDrawableTint::ControlNormal);state.toolbar_menu_items.insert("toolbar".into(),items);let viewport=Rect{x:0.,y:0.,width:430.,height:400.};let toolbar=Rect{x:0.,y:0.,width:430.,height:56.};for color in [Color(8,91,37,255),Color(210,170,70,255)] {ui.theme.on_surface_variant=color;let commands=ui.frame(Input::default(),viewport,0.,|f|{fixture::LAYOUT.render(f,toolbar,&mut state);});assert!(commands.iter().any(|c|matches!(c,DrawCommand::Image{image,..} if image.pixels().chunks_exact(4).any(|p|p[3]>0 && p[0]==color.0 && p[1]==color.1 && p[2]==color.2))));}}
#[test] fn reordered_menu_during_press_does_not_select_another_action(){use bhoo::android_xml::{AndroidToolbarMenuItem as Item,AndroidShowAsAction as Policy};let mut ui=Ui::default();let mut state=android_xml::LayoutState::default();fixture::install_drawables(&mut state);let make=|id,label:&str|Item{checkable:false,checked:false,exclusive:false,group_id:0,id,label:label.into(),icon:Some(MaterialIcon::Search),show_text_with_icon:false,icon_drawable:None,show_as_action:Policy::Always,enabled:true,visible:true};state.toolbar_menu_items.insert("toolbar".into(),vec![make(1,"One"),make(2,"Two")]);let b=Rect{x:0.,y:0.,width:500.,height:56.};let draw=|ui:&mut Ui,state:&mut android_xml::LayoutState,input|{let mut action=None;ui.frame(input,b,0.,|f|action=fixture::LAYOUT.render(f,b,state));action};draw(&mut ui,&mut state,Input::default());let rect=ui.semantics().iter().find(|n|n.label.as_ref()=="One").unwrap().bounds;let p=Some([rect.x+24.,rect.y+24.]);draw(&mut ui,&mut state,Input{pointer:p,pressed:true,time:1.,..Input::default()});state.toolbar_menu_items.get_mut("toolbar").unwrap().reverse();assert_eq!(draw(&mut ui,&mut state,Input{pointer:p,released:true,time:1.01,..Input::default()}),None);assert!(!state.toolbar_menu_clicked.contains_key("toolbar"));}
#[test] fn disabling_toolbar_dismisses_open_overflow(){use bhoo::android_xml::{AndroidToolbarMenuItem as Item,AndroidShowAsAction as Policy};static DISABLED:android_xml::Node=android_xml::Node{enabled:false,..fixture::LAYOUT};let mut ui=Ui::default();let mut state=android_xml::LayoutState::default();fixture::install_drawables(&mut state);state.toolbar_menu_items.insert("toolbar".into(),vec![Item{checkable:false,checked:false,exclusive:false,group_id:0,id:1,label:"Settings".into(),icon:None,show_text_with_icon:false,icon_drawable:None,show_as_action:Policy::Never,enabled:true,visible:true}]);let viewport=Rect{x:0.,y:0.,width:320.,height:400.};let b=Rect{x:0.,y:0.,width:320.,height:56.};let draw=|ui:&mut Ui,state:&mut android_xml::LayoutState,input,node:&'static android_xml::Node|{let mut action=None;ui.frame(input,viewport,0.,|f|action=node.render(f,b,state));action};draw(&mut ui,&mut state,Input::default(),&fixture::LAYOUT);let r=ui.semantics().iter().find(|n|n.label.as_ref()=="More options").unwrap().bounds;let p=Some([r.x+24.,r.y+24.]);draw(&mut ui,&mut state,Input{pointer:p,pressed:true,time:1.,..Input::default()},&fixture::LAYOUT);draw(&mut ui,&mut state,Input{pointer:p,released:true,time:1.01,..Input::default()},&fixture::LAYOUT);draw(&mut ui,&mut state,Input{time:1.3,..Input::default()},&fixture::LAYOUT);assert!(ui.semantics().iter().any(|n|n.label.as_ref()=="Settings"));draw(&mut ui,&mut state,Input{time:1.4,..Input::default()},&DISABLED);draw(&mut ui,&mut state,Input{time:1.8,..Input::default()},&DISABLED);assert!(!ui.semantics().iter().any(|n|n.label.as_ref()=="Settings"&&n.enabled));}
