#[test] fn xml_content_insets_respect_navigation_actions_and_rtl(){use bhoo::android_xml::{AndroidToolbarMenuItem as Item,AndroidShowAsAction as Policy};let mut ui=Ui::default();let mut state=android_xml::LayoutState::default();fixture::install_drawables(&mut state);let b=Rect{x:0.,y:0.,width:320.,height:56.};let draw=|ui:&mut Ui,state:&mut android_xml::LayoutState|ui.frame(Input::default(),b,0.,|f|{fixture::LAYOUT.render(f,b,state);});let commands=draw(&mut ui,&mut state);let title=commands.iter().find_map(|c|match c{DrawCommand::Text{text,bounds,..} if text.as_ref()=="Inbox"=>Some(*bounds),_=>None}).unwrap();assert_eq!(title.x,88.);assert!((title.y-8.657143).abs()<0.001);state.toolbar_menu_items.insert("toolbar".into(),vec![Item{checkable:false,checked:false,exclusive:false,group_id:0,id:1,label:"Search".into(),icon:Some(MaterialIcon::Search),show_text_with_icon:false,icon_drawable:None,show_as_action:Policy::Always,enabled:true,visible:true}]);draw(&mut ui,&mut state);let edit=ui.semantics().iter().find(|n|n.label.as_ref()=="Edit").unwrap().bounds;assert_eq!(edit.x,184.);state.rtl=true;let commands=draw(&mut ui,&mut state);let title=commands.iter().find_map(|c|match c{DrawCommand::Text{text,bounds,..} if text.as_ref()=="Inbox"=>Some(*bounds),_=>None}).unwrap();assert!((title.x+title.width-232.).abs()<0.01);let edit=ui.semantics().iter().find(|n|n.label.as_ref()=="Edit").unwrap().bounds;assert_eq!(edit.x,64.);}
