#[test] fn toolbar_ellipsizes_long_titles_and_subtitles_on_grapheme_boundaries(){static LONG:android_xml::Node=android_xml::Node{hint:"A long descriptive subtitle for this account",..fixture::LAYOUT};let mut ui=Ui::default();let mut state=android_xml::LayoutState::default();fixture::install_drawables(&mut state);state.text.insert("toolbar".into(),"👩‍👩‍👧‍👦 Café messages from the entire family".into());let b=Rect{x:0.,y:0.,width:280.,height:56.};let metrics=ui.text_metrics;let commands=ui.frame(Input::default(),b,0.,|f|{LONG.render(f,b,&mut state);});let rendered:Vec<_>=commands.iter().filter_map(|c|if let DrawCommand::Text{text,bounds,style,..}=c {if text.contains('…'){Some((text,bounds,style))}else{None}}else{None}).collect();assert_eq!(rendered.len(),2);for (text,bounds,style) in rendered {assert!(metrics.width(text,*style)<=bounds.width+0.01);assert!(!text.ends_with("\u{200d}…"));}}
#[test] fn toolbar_title_colors_resolve_xml_and_runtime_overrides(){let mut ui=Ui::default();let mut state=android_xml::LayoutState::default();fixture::install_drawables(&mut state);let b=Rect{x:0.,y:0.,width:400.,height:56.};let draw=|ui:&mut Ui,state:&mut android_xml::LayoutState|ui.frame(Input::default(),b,0.,|f|{fixture::LAYOUT.render(f,b,state);});let color=|cmds:&[DrawCommand],label:&str|cmds.iter().find_map(|c|match c{DrawCommand::Text{text,color,..} if text.as_ref()==label=>Some(*color),_=>None}).unwrap();let commands=draw(&mut ui,&mut state);assert_eq!(color(&commands,"Inbox"),Color(24,61,46,255));assert_eq!(color(&commands,"Personal account"),Color(76,103,87,255));state.toolbar_title_colors.insert("toolbar".into(),Color(1,2,3,255));state.toolbar_subtitle_colors.insert("toolbar".into(),Color(4,5,6,128));let commands=draw(&mut ui,&mut state);assert_eq!(color(&commands,"Inbox"),Color(1,2,3,255));assert_eq!(color(&commands,"Personal account"),Color(4,5,6,128));}
#[test] fn toolbar_text_appearance_sets_sizes_weight_and_color_precedence(){let mut ui=Ui::default();let mut state=android_xml::LayoutState::default();fixture::install_drawables(&mut state);let b=Rect{x:0.,y:0.,width:400.,height:56.};let commands=ui.frame(Input::default(),b,0.,|f|{fixture::LAYOUT.render(f,b,&mut state);});let find=|label:&str|commands.iter().find_map(|c|match c{DrawCommand::Text{text,style,color,..} if text.as_ref()==label=>Some((*style,*color)),_=>None}).unwrap();let (title,color)=find("Inbox");assert_eq!(title.size,18.);assert_eq!(title.weight,700);assert_eq!(color,Color(24,61,46,255));let (subtitle,color)=find("Personal account");assert_eq!(subtitle.size,12.);assert_eq!(subtitle.weight,400);assert_eq!(color,Color(76,103,87,255));}
#[test]
fn toolbar_group_operations_change_only_matching_items() {
    use bhoo::android_xml::{AndroidToolbarMenuItem as Item, AndroidShowAsAction as Policy, allocate_android_toolbar_actions};
    let mut state=android_xml::LayoutState::default();
    let item=|id,group_id|Item{checkable:false,checked:false,exclusive:false,id,group_id,label:id.to_string(),icon:None,show_text_with_icon:false,icon_drawable:None,show_as_action:Policy::Never,enabled:true,visible:true};
    state.toolbar_menu_items.insert("toolbar".into(),vec![item(1,42),item(2,42),item(3,7)]);
    state.set_toolbar_group_enabled("toolbar",42,false);
    let items=&state.toolbar_menu_items["toolbar"];
    assert_eq!(items.iter().map(|i|i.enabled).collect::<Vec<_>>(),vec![false,false,true]);
    state.set_toolbar_group_visible("toolbar",42,false);
    let (_,overflow)=allocate_android_toolbar_actions(&state.toolbar_menu_items["toolbar"],4);
    assert_eq!(overflow,vec![2]);
    state.set_toolbar_group_visible("toolbar",42,true);
    state.set_toolbar_group_enabled("toolbar",42,true);
    assert!(state.toolbar_menu_items["toolbar"].iter().all(|i|i.enabled&&i.visible));
}
#[test]
fn grouped_requested_actions_move_together_when_width_is_insufficient() {
    use bhoo::android_xml::{AndroidToolbarMenuItem as Item, AndroidShowAsAction as Policy, allocate_android_toolbar_actions};
    let item=|id,group_id,show_as_action|Item{checkable:false,checked:false,exclusive:false,id,group_id,label:id.to_string(),icon:None,show_text_with_icon:false,icon_drawable:None,show_as_action,enabled:true,visible:true};
    let items=vec![item(1,42,Policy::IfRoom),item(2,42,Policy::IfRoom),item(3,0,Policy::Never)];
    assert_eq!(allocate_android_toolbar_actions(&items,3),(vec![0,1],vec![2]));
    assert_eq!(allocate_android_toolbar_actions(&items,2),(vec![],vec![0,1,2]));
    let independent=vec![item(1,0,Policy::IfRoom),item(2,0,Policy::IfRoom),item(3,0,Policy::Never)];
    assert_eq!(allocate_android_toolbar_actions(&independent,2),(vec![0],vec![1,2]));
    let hidden=vec![item(1,42,Policy::IfRoom),Item{visible:false,..item(2,42,Policy::IfRoom)},item(3,0,Policy::Never)];
    assert_eq!(allocate_android_toolbar_actions(&hidden,2),(vec![0],vec![2]));
}
#[test]
fn exclusive_checkable_menu_items_follow_android_set_checked() {
    use bhoo::android_xml::{AndroidToolbarMenuItem as Item, AndroidShowAsAction as Policy};
    let item=|id,group_id,exclusive,checked|Item{id,group_id,label:id.to_string(),icon:None,show_text_with_icon:false,icon_drawable:None,show_as_action:Policy::Never,enabled:true,visible:true,checkable:true,checked,exclusive};
    let mut state=android_xml::LayoutState::default();
    state.toolbar_menu_items.insert("toolbar".into(),vec![item(1,42,true,true),item(2,42,true,false),item(3,7,false,true)]);
    state.set_toolbar_item_checked("toolbar",2,true);
    assert_eq!(state.toolbar_menu_items["toolbar"].iter().map(|x|x.checked).collect::<Vec<_>>(),vec![false,true,true]);
    state.set_toolbar_item_checked("toolbar",1,false);
    assert_eq!(state.toolbar_menu_items["toolbar"].iter().map(|x|x.checked).collect::<Vec<_>>(),vec![true,false,true]);
    state.set_toolbar_item_checked("toolbar",3,false);
    assert!(!state.toolbar_menu_items["toolbar"][2].checked);
}
#[test] fn toolbar_with_text_action_reserves_space_and_obeys_configuration() {
    use bhoo::android_xml::{AndroidToolbarMenuItem as Item,AndroidShowAsAction as Policy};
    let bounds=Rect{x:0.,y:0.,width:400.,height:56.};let mut ui=Ui::default();let mut state=android_xml::LayoutState::default();fixture::install_drawables(&mut state);
    state.toolbar_menu_items.insert("toolbar".into(),vec![Item{id:123,group_id:0,label:"Search".into(),icon:Some(MaterialIcon::Search),icon_drawable:None,show_text_with_icon:true,show_as_action:Policy::IfRoom,enabled:true,visible:true,checkable:false,checked:false,exclusive:false}]);
    state.menu_allow_text_with_icon=Some(false);let commands=ui.frame(Input::default(),bounds,0.,|f|{fixture::LAYOUT.render(f,bounds,&mut state);});
    assert!(!commands.iter().any(|c|matches!(c,DrawCommand::Text{text,..} if text.as_ref()=="Search")));let narrow=ui.semantics().iter().find(|n|n.label.as_ref()=="Search").unwrap().bounds.width;
    state.menu_allow_text_with_icon=Some(true);let commands=ui.frame(Input{time:0.1,..Input::default()},bounds,0.,|f|{fixture::LAYOUT.render(f,bounds,&mut state);});
    assert!(commands.iter().any(|c|matches!(c,DrawCommand::Text{text,..} if text.as_ref()=="Search")));let wide=ui.semantics().iter().find(|n|n.label.as_ref()=="Search").unwrap().bounds.width;assert!(wide>=narrow*2.);
}
#[test] fn toolbar_with_text_reserves_overflow_only_once_at_phone_width(){
    use bhoo::android_xml::{AndroidToolbarMenuItem as Item,AndroidShowAsAction as Policy};
    let bounds=Rect{x:0.,y:0.,width:342.,height:56.};let mut ui=Ui::default();let mut state=android_xml::LayoutState::default();fixture::install_drawables(&mut state);state.menu_allow_text_with_icon=Some(true);
    let make=|id,label:&str,policy,icon,show_text_with_icon|Item{id,group_id:0,label:label.into(),icon,icon_drawable:None,show_text_with_icon,show_as_action:policy,enabled:true,visible:true,checkable:false,checked:false,exclusive:false};
    state.toolbar_menu_items.insert("toolbar".into(),vec![make(1,"Search",Policy::IfRoom,Some(MaterialIcon::Search),true),make(2,"More",Policy::Never,None,false)]);
    ui.frame(Input::default(),bounds,0.,|f|{fixture::LAYOUT.render(f,bounds,&mut state);});
    assert_eq!(ui.semantics().iter().find(|n|n.label.as_ref()=="Search").unwrap().bounds.width,96.);assert!(ui.semantics().iter().any(|n|n.label.as_ref()=="More options"));
}
